            new Product { Id=89, Name="Kit de démarrage Arduino UNO R3 – Basic", Description="Kit éducatif complet combinant une carte Arduino UNO R3, un moteur pas à pas pour l'apprentissage du contrôle de mouvement et un module RFID pour la gestion d'identification par carte ou badge. Inclut câbles, résistances et guide de projets pas à pas. Idéal pour les formations techniques.", Price=22000m, ImageUrl="/images/products/Kit 22k.jpeg",          CategoryId=7, Stock=50, IsAvailable=true, CreatedAt=DateTime.Parse("2026-03-10T16:47:51Z") },
