            new Product { Id=92, Name="Coffret complet d'initiation électronique", Description="Kit d'initiation complet présenté dans un coffret de rangement compartimenté, idéal pour débutants, étudiants et passionnés d'électronique. Contient une carte compatible UNO R3, breadboard, résistances, condensateurs, LEDs, capteurs, modules de communication et guide de projets complet. Tout le nécessaire pour commencer.", Price=60000m, ImageUrl="/images/products/Initiation Électronique.png", CategoryId=7, Stock=30, IsAvailable=true, CreatedAt=DateTime.Parse("2026-03-10T16:21:31Z") },
