            new Product { Id=95, Name="Transistor MOSFET IRLZ44N – Canal N", Description="Transistor MOSFET canal N IRLZ44N à faible résistance RDS(on) (22 mΩ typ.), compatible avec les niveaux logiques 3,3V et 5V. Tension drain-source max 55V, courant 47A en continu. Idéal pour piloter des charges de puissance (moteurs, LEDs, solénoïdes) depuis un microcontrôleur sans circuit de commande supplémentaire.", Price=500m,   ImageUrl="/images/products/IRLZ44N.jpg",          CategoryId=9, Stock=100, IsAvailable=true, CreatedAt=DateTime.Parse("2026-03-09T18:25:29Z") },
