            new Product { Id=97,  Name="Module Peltier TEC1-12706", Description="Module thermoélectrique Peltier TEC1-12706 basé sur l'effet Peltier : refroidit d'un côté et chauffe de l'autre en courant continu (12V, 6A max). Utilisé pour les mini-réfrigérateurs, les refroidisseurs de composants électroniques et les régulateurs thermiques embarqués.", Price=2500m,  ImageUrl="/images/products/peltier.jpeg",         CategoryId=10, Stock=10,  IsAvailable=true, CreatedAt=DateTime.Parse("2026-03-10T16:21:46Z") },
            new Product { Id=98,  Name="Micro moteur DC 716 (7×16 mm)", Description="Micro moteur DC 716 (7×16 mm) à grande vitesse (15 000–55 000 tr/min selon alimentation), conçu pour les mini drones, hélicoptères DIY et petits robots. Alimentation 3,7V–8,4V, poids inférieur à 5g. Les hélices compatibles sont vendues séparément.", Price=2000m,  ImageUrl="/images/products/Mini moteur DC.jpg",   CategoryId=10, Stock=100, IsAvailable=true, CreatedAt=DateTime.Parse("2026-03-09T18:25:56Z") },
