            new Product { Id=112, Name="Module relais 8 canaux", Description="Module relais électromécanique 8 canaux permettant de contrôler huit charges électriques indépendantes (AC ou DC jusqu'à 250V/10A) depuis un microcontrôleur. Idéal pour l'automatisation industrielle, les systèmes domotiques et les projets nécessitant de nombreuses sorties de puissance.", Price=8000m,  ImageUrl="/images/products/Relais 8 canaux.jpeg", CategoryId=10, Stock=60, IsAvailable=true, CreatedAt=DateTime.Parse("2026-03-10T16:30:45Z") },
